package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;
@Entity @Table(name="inventory_movement") public class MovimientoInventario {
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;
 @Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;
 @Column(name="movement_number",nullable=false,updatable=false,length=30)private String numero;@Column(name="warehouse_id",nullable=false,updatable=false)private UUID almacenId;@Column(name="product_id",nullable=false,updatable=false)private UUID productoId;
 @Column(name="movement_date",nullable=false,updatable=false)private LocalDate fecha;@Column(name="effective_at",nullable=false,updatable=false)private OffsetDateTime fechaEfectiva;
 @Column(nullable=false,updatable=false,precision=19,scale=4)private BigDecimal quantity;@Column(nullable=false,updatable=false,length=10)private String direction;@Column(name="movement_type",nullable=false,updatable=false,length=40)private String tipo;@Column(name="reference_type",nullable=false,updatable=false,length=40)private String tipoReferencia;@Column(name="reference_id",nullable=false,updatable=false)private UUID referenciaId;
 @Column(name="origin_document_number",nullable=false,updatable=false,length=40)private String documentoOrigen;@Column(name="origin_reference",updatable=false,length=100)private String referenciaOrigen;@Column(name="source_line_id",updatable=false)private UUID lineaOrigenId;@Column(name="unit_of_measure_id",nullable=false,updatable=false)private UUID unidadMedidaId;
 @Column(name="source_quantity",nullable=false,updatable=false,precision=19,scale=4)private BigDecimal cantidadOrigen;@Column(name="base_quantity",nullable=false,updatable=false,precision=19,scale=4)private BigDecimal cantidadBase;@Column(name="conversion_factor",nullable=false,updatable=false,precision=19,scale=8)private BigDecimal factorConversion;@Column(name="source_key",nullable=false,updatable=false,length=300)private String claveOrigen;
 @Column(name="reversal_of_id",updatable=false)private UUID reversoDeId;@Column(name="created_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime creadoEn;@Column(name="created_by",nullable=false,updatable=false)private UUID creadoPor;
 protected MovimientoInventario(){}
 public MovimientoInventario(UUID t,UUID e,String n,UUID a,UUID p,LocalDate f,BigDecimal q,String d,String ti,String tr,UUID r,String doc,String ref,UUID line,UUID unit,UUID re,UUID u){tenantId=t;empresaId=e;numero=n;almacenId=a;productoId=p;fecha=f;fechaEfectiva=ZonedDateTime.of(f,LocalTime.now(),ZoneId.systemDefault()).toOffsetDateTime();quantity=q;direction=d;tipo=ti;tipoReferencia=tr;referenciaId=r;documentoOrigen=doc;referenciaOrigen=ref;lineaOrigenId=line;unidadMedidaId=unit;cantidadOrigen=q;cantidadBase=q;factorConversion=BigDecimal.ONE;reversoDeId=re;creadoPor=u;claveOrigen=clave(tr,r,a,p,d,line);}
 public static String clave(String tipo,UUID referencia,UUID almacen,UUID producto,String direccion,UUID linea){return tipo+":"+referencia+":"+almacen+":"+producto+":"+direccion+":"+(linea==null?"-":linea);}
 public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getEmpresaId(){return empresaId;}public String getNumero(){return numero;}public UUID getAlmacenId(){return almacenId;}public UUID getProductoId(){return productoId;}public LocalDate getFecha(){return fecha;}public OffsetDateTime getFechaEfectiva(){return fechaEfectiva;}public BigDecimal getCantidad(){return quantity;}public String getDireccion(){return direction;}public String getTipo(){return tipo;}public String getTipoReferencia(){return tipoReferencia;}public UUID getReferenciaId(){return referenciaId;}public String getDocumentoOrigen(){return documentoOrigen;}public String getReferenciaOrigen(){return referenciaOrigen;}public UUID getLineaOrigenId(){return lineaOrigenId;}public UUID getUnidadMedidaId(){return unidadMedidaId;}public BigDecimal getCantidadOrigen(){return cantidadOrigen;}public BigDecimal getCantidadBase(){return cantidadBase;}public BigDecimal getFactorConversion(){return factorConversion;}public UUID getReversoDeId(){return reversoDeId;}public OffsetDateTime getCreadoEn(){return creadoEn;}public UUID getCreadoPor(){return creadoPor;}
}
